<?php
require_once __DIR__.'/SpreadsheetRows.php';require_once __DIR__.'/SafeFormula.php';require_once __DIR__.'/PayrollRepository.php';require_once __DIR__.'/../services/FormulaRuntime.php';
class PayrollImportService
{
    public static function templateRows(): array{$fields=Database::fetchAll("SELECT field_key,label FROM payroll_fields WHERE active=1 AND field_key<>'employee_no' ORDER BY sort_order,id");return [array_merge(['employee_no','period_key'],array_column($fields,'field_key')),array_merge(['10001','1405-01'],array_fill(0,count($fields),''))];}
    public static function preview(string $path,string $fileName,int $periodId,int $userId): int{$period=PayrollRepository::assertPeriodEditable($periodId);if(in_array($period['status'],['published','locked'],true))throw new InvalidArgumentException('برای ایمپورت، دوره باید در وضعیت پیش‌نویس یا ایمپورت‌شده باشد.');$ext=strtolower(pathinfo($fileName,PATHINFO_EXTENSION));$rows=SpreadsheetRows::associative(SpreadsheetRows::read($path,$ext));$fields=Database::fetchAll('SELECT * FROM payroll_fields WHERE active=1 ORDER BY sort_order,id');$fieldKeys=array_flip(array_column($fields,'field_key'));Database::execute('INSERT INTO payroll_import_batches(period_id,file_name,imported_by,total_rows,status,created_at) VALUES(?,?,?, ?,"preview",NOW())',[$periodId,$fileName,$userId,count($rows)]);$batch=(int)Database::lastInsertId();$success=0;$errors=0;$seen=[];foreach($rows as $row){$messages=[];$no=trim((string)($row['employee_no']??''));if($no==='')$messages[]='شماره پرسنلی خالی است.';elseif(isset($seen[$no]))$messages[]='شماره پرسنلی در فایل تکراری است.';$seen[$no]=true;$user=$no!==''?Database::fetch('SELECT id FROM users WHERE employee_no=?',[$no]):null;if(!$user)$messages[]='کاربر متناظر با شماره پرسنلی پیدا نشد.';if(trim((string)($row['period_key']??''))!==$period['period_key'])$messages[]='کلید دوره با دوره انتخابی یکسان نیست.';foreach($row as $key=>$value){if(str_starts_with($key,'_')||in_array($key,['employee_no','period_key'],true))continue;if(!isset($fieldKeys[$key]))$messages[]='ستون ناشناخته: '.$key;}$status=$messages?'error':'valid';$messages?$errors++:$success++;Database::execute('INSERT INTO payroll_import_rows(batch_id,source_row,employee_no,raw_data_json,status,error_message,created_at) VALUES(?,?,?,?,?,?,NOW())',[$batch,(int)$row['_row'],$no?:null,json_encode($row,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$status,$messages?implode(' ',$messages):null]);}Database::execute('UPDATE payroll_import_batches SET success_count=?,error_count=? WHERE id=?',[$success,$errors,$batch]);return $batch;}
    public static function commit(int $batchId): array{$pdo=Database::connection();$pdo->beginTransaction();try{$batch=Database::fetch('SELECT b.*,p.status period_status,p.end_date period_end_date FROM payroll_import_batches b JOIN payroll_periods p ON p.id=b.period_id WHERE b.id=? FOR UPDATE',[$batchId]);if(!$batch||$batch['status']!=='preview')throw new InvalidArgumentException('Batch قابل ثبت نیست.');if(in_array($batch['period_status'],['published','locked','cancelled'],true))throw new InvalidArgumentException('وضعیت دوره اجازه ثبت ایمپورت را نمی‌دهد.');$fields=Database::fetchAll('SELECT * FROM payroll_fields WHERE active=1 ORDER BY sort_order,id');$rows=Database::fetchAll("SELECT * FROM payroll_import_rows WHERE batch_id=? AND status='valid' ORDER BY source_row",[$batchId]);$count=0;foreach($rows as $row){$data=json_decode($row['raw_data_json'],true)?:[];$user=Database::fetch('SELECT u.*,ou.title unit_title,orr.title job_title FROM users u LEFT JOIN org_units ou ON ou.id=u.org_unit_id LEFT JOIN org_roles orr ON orr.id=u.org_role_id WHERE u.employee_no=?',[$row['employee_no']]);if(!$user){Database::execute("UPDATE payroll_import_rows SET status='skipped',error_message='کاربر پیدا نشد.' WHERE id=?",[$row['id']]);continue;}$values=[];foreach($fields as $field){$key=$field['field_key'];$raw=$data[$key]??$field['default_value']??'';$system=['employee_no'=>$user['employee_no'],'full_name'=>$user['name'],'department'=>$user['unit_title']?:$user['department'],'job_title'=>$user['job_title']?:$user['role_key']];if($field['calculation_type']==='system'&&array_key_exists($key,$system))$raw=$system[$key];$values[$key]=in_array($field['data_type'],['number','money','percent'],true)?SpreadsheetRows::number($raw):(string)$raw;}foreach($fields as $field)if($field['calculation_type']==='formula'){if(!empty($field['formula_definition_id'])){$runtime=FormulaRuntime::evaluateDefinition((int)$field['formula_definition_id'],$values,$batch['period_end_date']??null);if($runtime===null)throw new RuntimeException('فرمول فعال فیلد «'.(string)$field['label'].'» در دوره انتخابی موجود نیست.');$values[$field['field_key']]=(float)$runtime['final_result'];}else{$values[$field['field_key']]=SafeFormula::evaluate($field['formula'],$values);}}$earnings=0.0;$deductions=0.0;foreach($fields as $field){$number=(float)($values[$field['field_key']]??0);if($field['field_type']==='earning')$earnings+=$number;if($field['field_type']==='deduction')$deductions+=$number;}$net=$earnings-$deductions;$values['total_earnings']=$earnings;$values['total_deductions']=$deductions;$values['net_pay']=$net;$tracking=hash('sha256',$batch['period_id'].'|'.$user['id'].'|'.$user['employee_no']);Database::execute('INSERT INTO payroll_slips(period_id,user_id,employee_no,gross_amount,total_earnings,total_deductions,net_pay,status,tracking_code,created_at,updated_at) VALUES(?,?,?,?,?,?,?,"ready",?,NOW(),NOW()) ON DUPLICATE KEY UPDATE employee_no=VALUES(employee_no),gross_amount=VALUES(gross_amount),total_earnings=VALUES(total_earnings),total_deductions=VALUES(total_deductions),net_pay=VALUES(net_pay),status=IF(status="published","published","ready"),updated_at=NOW()',[(int)$batch['period_id'],(int)$user['id'],$user['employee_no'],$earnings,$earnings,$deductions,$net,$tracking]);$slip=Database::fetch('SELECT id FROM payroll_slips WHERE period_id=? AND user_id=?',[(int)$batch['period_id'],(int)$user['id']]);foreach($fields as $field){$value=$values[$field['field_key']]??'';$numeric=in_array($field['data_type'],['number','money','percent'],true)?(float)$value:null;Database::execute('INSERT INTO payroll_slip_values(slip_id,field_id,field_key,label,value_text,value_number,sort_order,created_at) VALUES(?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE field_id=VALUES(field_id),label=VALUES(label),value_text=VALUES(value_text),value_number=VALUES(value_number),sort_order=VALUES(sort_order)',[(int)$slip['id'],(int)$field['id'],$field['field_key'],$field['label'],is_scalar($value)?(string)$value:'',$numeric,(int)$field['sort_order']]);}Database::execute("UPDATE payroll_import_rows SET status='committed',error_message=NULL WHERE id=?",[$row['id']]);$count++;}Database::execute("UPDATE payroll_import_batches SET status='committed',success_count=?,committed_at=NOW() WHERE id=?",[$count,$batchId]);Database::execute("UPDATE payroll_periods SET status='imported',updated_at=NOW() WHERE id=? AND status='draft'",[(int)$batch['period_id']]);$pdo->commit();return ['committed'=>$count];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
}
